    {
      "tag": "path",
      "attrs": {
        "d": "M12 3v3m0 12v3"
      }
    }
  ],
  "accents": []
};

export const meta = {
  "slug": "tabler-currency-dollar",
  "family": "tabler",
  "name": "currency-dollar",
  "category": "Commerce",
  "motion": "coin",
  "component": "createTablerCurrencyDollarIcon"
};

export function createTablerCurrencyDollarIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
